{
  "items": [
    {
      "title": "Eurostat – Digital Economy and Society Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/digital-economy-and-society/information-data",
      "justification": "A comprehensive collection of official European statistics on the development of the information society, including Germany. Provides annual datasets covering the 2010s and 2020s on internet access, digital technology adoption, e-commerce, e-government, digital skills, and online activities. Particularly useful for examining long-term trends in Germany and comparing them with other European countries."
    },
    {
      "title": "Eurostat – ICT Usage in Households and by Individuals (Microdata)",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/microdata/collections-research/survey-ict-use-households-individuals",
      "justification": "Provides harmonized survey microdata for 2008–2025, with country availability documented by Eurostat. Covers individual and household internet usage, digital skills, online shopping, e-government, privacy, and emerging technologies. Includes demographic and socioeconomic characteristics such as age, gender, education, employment, and household income. Especially valuable for investigating digital inequality and information society development in Germany. Access to scientific-use microdata requires authorization."
    },
    {
      "title": "Destatis GENESIS-Online – ICT Usage in Private Households (Statistics 12231)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistics",
      "justification": "Official German statistical database containing the ICT Usage in Private Households survey (IKT-Nutzung in privaten Haushalten, code 12231). Includes historical data on computer ownership, internet access, online shopping, internet activities, and digital technology use. Provides breakdowns by age, gender, household income, and geographical area. Relevant for studying changes in Germany's information society throughout the 2010s and 2020s. Search for statistical code 12231."
    },
    {
      "title": "Destatis GENESIS-Online – ICT Usage in Enterprises (Statistics 52911)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistics",
      "justification": "Official German statistics on the adoption and use of information and communication technologies by businesses. Dataset code 52911 covers ICT indicators for enterprises, with breakdowns by industry and company size. Useful for analyzing business digitalization, the diffusion of digital technologies, and Germany's transition toward a digital economy during the 2010s and 2020s."
    },
    {
      "title": "Initiative D21 – D21 Digital Index (2013–2020s)",
      "url_or_doi": "https://initiatived21.de/publikationen/d21-digital-index",
      "justification": "Long-running German research series tracking the digital transformation of society since 2013. Examines internet usage, digital competencies, attitudes toward digital technologies, digital participation, and differences between demographic groups. Particularly relevant for studying the social dimensions of the information society in Germany. The landing page provides historical study editions and statistical findings. It primarily offers reports and aggregated results rather than a consistently downloadable raw-data series."
    },
    {
      "title": "Initiative D21 – (N)ONLINER Atlas (2010–2012)",
      "url_or_doi": "https://initiatived21.de/publikationen/d21-digital-index",
      "justification": "Historical German research series documenting internet adoption and the digital divide before the introduction of the D21 Digital Index. The landing page provides the 2010, 2011, and 2012 editions, including statistics on internet users, non-users, and potential future users. Useful for establishing baseline conditions at the beginning of the 2010s and analyzing the expansion of internet participation in Germany."
    },
    {
      "title": "Eurostat – Households with Access to the Internet at Home (isoc_r_iacc_h)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/ISOC_R_IACC_H/default/table?lang=en",
      "justification": "Annual statistical dataset measuring the percentage of households with internet access at home. Includes Germany and European regional breakdowns where available. Particularly useful for examining the expansion of household connectivity, geographical inequalities, and regional digital infrastructure development across the 2010s and 2020s. Data can be filtered by geography and year and downloaded for quantitative analysis."
    },
    {
      "title": "Eurostat – Comprehensive Digital Economy and Society Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/de/web/digital-economy-and-society/database/comprehensive-database",
      "justification": "Provides comprehensive downloadable statistical databases covering ICT adoption and digital society indicators in European countries, including Germany. Contains historical information on household connectivity, individual internet activities, online public services, and other dimensions of digitalization. Particularly suitable for constructing longitudinal datasets covering Germany during the 2010s and 2020s."
    },
    {
      "title": "Bundesnetzagentur – Broadband Atlas (Breitbandatlas)",
      "url_or_doi": "https://bundesnetzagentur.de/GIGA/DE/Breitbandatlas/start.html",
      "justification": "Official German telecommunications infrastructure dataset documenting broadband availability across Germany. Provides geographically detailed information on broadband coverage, connection speeds, and technologies. Downloadable coverage data are available from June 2022 onward. Especially useful for analyzing spatial digital inequalities, urban-rural differences, and broadband infrastructure development during the 2020s."
    },
    {
      "title": "Deutschlandatlas – Broadband Availability in Germany",
      "url_or_doi": "https://deutschlandatlas.bund.de/karten/wie-wir-uns-vernetzen/breitbandversorgung",
      "justification": "Official German regional information resource providing geographical indicators of broadband connectivity. Enables comparisons of digital infrastructure availability across German regions and districts. Particularly relevant for investigating geographical disparities in access to the information society, including differences between urban and rural communities. The landing page includes an open-data section."
    },
    {
      "title": "Destatis – Information and Communication Technologies in Households",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Income-Consumption-Living-Conditions/Use-Information-Technologies/Methods/ICT.html",
      "justification": "Official methodological documentation for Germany's household ICT survey. Explains the collection of statistics on computer use, internet access, online behavior, and digital technologies. Valuable for interpreting German information society datasets from the 2010s and 2020s, evaluating survey comparability, and identifying changes in statistical methodology. This is a methodological source rather than a direct dataset download."
    },
    {
      "title": "Destatis – IT Usage in Germany (IT-Nutzung)",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Einkommen-Konsum-Lebensbedingungen/IT-Nutzung/_inhalt.html",
      "justification": "Official German statistical topic page presenting indicators and publications about internet usage, digital inclusion, online activities, and access to information technologies. Provides access to relevant statistical resources and links to GENESIS-Online. Useful for identifying official German data and examining changes in the digital participation of households and individuals during the 2010s and 2020s."
    },
    {
      "title": "Eurostat – Digital Inclusion Indicators",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/employment-and-social-inclusion-indicators/digital-inclusion",
      "justification": "Official European statistical resource focused on digital inclusion and participation in the information society. Draws on annual ICT household and individual surveys covering Germany and other EU countries. Particularly useful for investigating inequalities in internet access, digital skills, and participation in digital activities among different population groups during the 2010s and 2020s."
    }
  ]
}
